import assert from 'node:assert/strict';

const mod=(n,m)=>((n%m)+m)%m;
const add=(x,y)=>x.map((a,i)=>mod(a+y[i],12));
const scale=(a,x)=>x.map(v=>mod(a*v,12));
const key=x=>x.join(',');
const GI=[
  [0,8,0,0,0],
  [8,0,0,0,0],
  [0,0,-2,0,0],
  [0,0,0,0,-18],
  [0,0,0,-18,0],
];
const mv=(A,x)=>A.map(r=>r.reduce((s,a,i)=>s+a*x[i],0));
const dot=(x,y)=>x.reduce((s,a,i)=>s+a*y[i],0);

// Coordinates are in the I_H basis (p,q,u,z,y), cleared by 12.
// M/I_H is generated by v=p/2+q/4 and s=y/6.
const h4=[6,3,0,0,0];
const h6=[0,0,0,0,2];
// W_HM/I_H is generated by Wv=-p/4-q/2 and Ws=z/6.
const k4=[9,6,0,0,0];
const k6=[0,0,0,2,0];

const subgroup=(g4,g6)=>{
  const S=new Map();
  for(let a=0;a<4;a++)for(let b=0;b<6;b++){
    const x=add(scale(a,g4),scale(b,g6));S.set(key(x),x);
  }
  return S;
};
const HM=subgroup(h4,h6), HL=subgroup(k4,k6);
assert.equal(HM.size,24);
assert.equal(HL.size,24);
assert.deepEqual([...HM.keys()].filter(k=>HL.has(k)),['0,0,0,0,0']);

const qNumerator=x=>dot(x,mv(GI,x)); // q=(x.G.x)/(2*12^2), denominator 288
for(const x of HM.values())assert.equal(mod(qNumerator(x),288),0);
for(const x of HL.values())assert.equal(mod(qNumerator(x),288),0);

const bNumerator=(x,y)=>dot(x,mv(GI,y)); // b=(x.G.y)/12^2, denominator 144
assert.equal(mod(bNumerator(h4,k4),144),72);
assert.equal(mod(bNumerator(h6,k6),144),72);
assert.equal(mod(bNumerator(h4,k6),144),0);
assert.equal(mod(bNumerator(h6,k4),144),0);

// The pairing is (ac+bd)/2 and therefore factors through parity F2^2.
for(let a=0;a<4;a++)for(let b=0;b<6;b++)for(let c=0;c<4;c++)for(let d=0;d<6;d++){
  const x=add(scale(a,h4),scale(b,h6));
  const y=add(scale(c,k4),scale(d,k6));
  assert.equal(mod(bNumerator(x,y),144),72*((a*c+b*d)&1));
}

const radicalM=[];
for(let a=0;a<4;a++)for(let b=0;b<6;b++){
  const x=add(scale(a,h4),scale(b,h6));
  if([...HL.values()].every(y=>mod(bNumerator(x,y),144)===0))radicalM.push([a,b]);
}
assert.deepEqual(radicalM,[[0,0],[0,2],[0,4],[2,0],[2,2],[2,4]]);

const radicalL=[];
for(let c=0;c<4;c++)for(let d=0;d<6;d++){
  const y=add(scale(c,k4),scale(d,k6));
  if([...HM.values()].every(x=>mod(bNumerator(x,y),144)===0))radicalL.push([c,d]);
}
assert.deepEqual(radicalL,[[0,0],[0,2],[0,4],[2,0],[2,2],[2,4]]);

const addSets=(S,T)=>{
  const U=new Map();
  for(const x of S.values())for(const y of T.values()){const z=add(x,y);U.set(key(z),z);}
  return U;
};
const RM=new Map(radicalM.map(([a,b])=>{const x=add(scale(a,h4),scale(b,h6));return [key(x),x];}));
const RL=new Map(radicalL.map(([c,d])=>{const x=add(scale(c,k4),scale(d,k6));return [key(x),x];}));
const ambientNGlue=addSets(HM,RL);
const ambientWHNGlue=addSets(HL,RM);
assert.equal(ambientNGlue.size,144);
assert.equal(ambientWHNGlue.size,144);
for(const x of ambientNGlue.values())assert.equal(mod(qNumerator(x),288),0);
for(const x of ambientWHNGlue.values())assert.equal(mod(qNumerator(x),288),0);
const ambientIntersection=[...ambientNGlue.keys()].filter(k=>ambientWHNGlue.has(k));
assert.equal(ambientIntersection.length,36);
assert.equal(41472/(144*144),2);

const sum=new Set();
let isotropicElements=0;
for(let a=0;a<4;a++)for(let b=0;b<6;b++)for(let c=0;c<4;c++)for(let d=0;d<6;d++){
  const x=add(add(scale(a,h4),scale(b,h6)),add(scale(c,k4),scale(d,k6)));
  sum.add(key(x));
  if(mod(qNumerator(x),288)===0)isotropicElements++;
}
assert.equal(sum.size,576);
assert.equal(isotropicElements,360);

console.log('hadamard_overlattice_glue_pairing: PASS');
console.log('two_faces_are_transverse_isotropic_C4_plus_C6_glue_subgroups');
console.log('their_sum_has_order576_and_their_intersection_is_zero');
console.log('mutual_pairing_is_half_times_the_F2_squared_dot_product');
console.log('mutual_radical_on_each_face_is_C2_plus_C3_of_order6');
console.log('only_the_two_parity_bits_obstruct_combining_the_integral_faces');
console.log('face_glue_plus_opposite_radical_has_order144_and_reconstructs_a_determinant2_ambient_lattice');
console.log('the_two_ambient_glue_subgroups_intersect_in_order36');
console.log('isotropic_elements_in_the_576_element_sum=360_not_a_subgroup');
